import{_ as t,o as s,c as r,a2 as a}from"./chunks/framework.ChIlRNAd.js";const g=JSON.parse('{"title":"Nettoyage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/cleanup.md","filePath":"fr/guide/cleanup.md"}'),n={name:"fr/guide/cleanup.md"};function o(i,e,l,u,d,p){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="nettoyage" tabindex="-1">Nettoyage <a class="header-anchor" href="#nettoyage" aria-label="Permalink to &quot;Nettoyage&quot;">​</a></h1><p>La page <strong>Nettoyage</strong> (<code>/cleanup</code>) sert à récupérer de l&#39;espace en peu de gestes. Son en-tête résume le gain possible : « 6,1 Go récupérables. Les 8 premiers expéditeurs pèsent 4,6 Go. »</p><p>Deux onglets : <strong>Expéditeurs &amp; newsletters</strong> et <strong>Gros mails &amp; pièces jointes</strong>.</p><hr><h2 id="expediteurs-newsletters" tabindex="-1">Expéditeurs &amp; newsletters <a class="header-anchor" href="#expediteurs-newsletters" aria-label="Permalink to &quot;Expéditeurs &amp; newsletters&quot;">​</a></h2><h3 id="analyser-la-boite" tabindex="-1">Analyser la boîte <a class="header-anchor" href="#analyser-la-boite" aria-label="Permalink to &quot;Analyser la boîte&quot;">​</a></h3><p>Au premier passage : « Aucune analyse pour ce compte ». Cliquez sur <strong>Analyser la boîte</strong> : Nid regroupe par expéditeur les mails de listes de diffusion et de newsletters. L&#39;analyse tourne en arrière-plan, vous pouvez quitter la page.</p><p>Ensuite, la date de la dernière analyse s&#39;affiche (« Analyse du … ») avec <strong>Relancer l&#39;analyse</strong>.</p><h3 id="liste-des-expediteurs" tabindex="-1">Liste des expéditeurs <a class="header-anchor" href="#liste-des-expediteurs" aria-label="Permalink to &quot;Liste des expéditeurs&quot;">​</a></h3><p>Pour chaque expéditeur : <strong>Expéditeur</strong>, <strong>Adresse</strong>, <strong>Taille</strong>, <strong>Mails</strong>, <strong>Jamais ouverts</strong>, et ses actions.</p><ul><li><strong>Trier par</strong> : <strong>Nombre de mails</strong>, <strong>Taille</strong> ou <strong>Jamais ouverts</strong>.</li><li><strong>Newsletters uniquement (List-Unsubscribe)</strong> : ne garde que les expéditeurs qui proposent un désabonnement automatique.</li></ul><p>Le tri et le filtre sont gardés dans l&#39;adresse de la page.</p><h3 id="actions-sur-un-expediteur" tabindex="-1">Actions sur un expéditeur <a class="header-anchor" href="#actions-sur-un-expediteur" aria-label="Permalink to &quot;Actions sur un expéditeur&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effet</th></tr></thead><tbody><tr><td><strong>Se désabonner et nettoyer</strong></td><td>désabonnement, puis tous ses mails vers la corbeille Gmail</td></tr><tr><td><strong>Tout supprimer</strong></td><td>tous ses mails vers la corbeille Gmail, sans désabonnement</td></tr><tr><td><strong>Toujours faire ça</strong></td><td>ouvre le formulaire de <a href="./rules.html#creer-une-regle">règle</a> pré-rempli avec l&#39;expéditeur, pour traiter aussi ses prochains mails</td></tr></tbody></table><p>Sur mobile, le bouton <code>⋯</code> d&#39;une carte ouvre ces actions dans un panneau.</p><h4 id="se-desabonner-et-nettoyer" tabindex="-1">Se désabonner et nettoyer <a class="header-anchor" href="#se-desabonner-et-nettoyer" aria-label="Permalink to &quot;Se désabonner et nettoyer&quot;">​</a></h4><p>Une confirmation s&#39;affiche : « Se désabonner de {expéditeur} ? ». La page de désabonnement de l&#39;expéditeur s&#39;ouvre dans un nouvel onglet : <strong>le désabonnement est définitif</strong>. Ses mails partent ensuite vers la corbeille Gmail.</p><p>Si l&#39;expéditeur ne fournit pas d&#39;en-tête <code>List-Unsubscribe</code>, le bouton est désactivé avec la mention « Cet expéditeur ne propose pas de désabonnement automatique » ; <strong>Tout supprimer</strong> et <strong>Toujours faire ça</strong> restent disponibles.</p><h4 id="annulation-et-progression" tabindex="-1">Annulation et progression <a class="header-anchor" href="#annulation-et-progression" aria-label="Permalink to &quot;Annulation et progression&quot;">​</a></h4><p>La suppression des mails (après désabonnement ou via <strong>Tout supprimer</strong>) affiche le toast « Suppression de N mails dans 10 s » avec <strong>Annuler</strong>, comme dans <a href="./mails.html#annuler">Mails</a>. La progression s&#39;affiche ensuite sur la ligne de l&#39;expéditeur, avec <strong>Arrêter</strong>. La tâche est aussi visible dans <a href="./activity.html">Activité</a>.</p><hr><h2 id="gros-mails-pieces-jointes" tabindex="-1">Gros mails &amp; pièces jointes <a class="header-anchor" href="#gros-mails-pieces-jointes" aria-label="Permalink to &quot;Gros mails &amp; pièces jointes&quot;">​</a></h2><p>Les pièces jointes les plus lourdes du compte, triées par taille. Le résumé indique « N pièces jointes · taille ».</p><p><strong>Source</strong> :</p><ul><li><strong>Gmail</strong> : les mails Gmail avec une pièce jointe de plus de 100 Ko. Cochez des lignes pour <strong>Sauvegarder sur le NAS</strong> ou <strong>Supprimer</strong> les mails correspondants (suppression annulable 10 s).</li><li><strong>Archives (NAS)</strong> : les pièces jointes déjà archivées. Ces mails ne sont plus traités ici ; téléchargement seulement.</li></ul><p>Colonnes : <strong>Fichier</strong>, <strong>Mail</strong> (objet), <strong>Taille</strong>, <strong>Date</strong>, et un bouton de téléchargement.</p><p>Pour toutes les pièces jointes, avec recherche et pagination, voir la page <a href="./attachments.html">Pièces jointes</a>.</p>',27)])])}const m=t(n,[["render",o]]);export{g as __pageData,m as default};
